  "geracao_sequencia_aleatoria": {"julgamento": "Low", "justificativa": "O artigo relata que a randomização foi realizada usando a tecnologia automatizada do site Randomisation.com."},
  "ocultacao_alocacao": {"julgamento": "High", "justificativa": "Os autores descrevem o uso do método de envelopes fechados, o que é considerado uma forma ineficaz de ocultação da alocação segundo os padrões da ferramenta Cochrane."},
  "cegamento_participantes_equipe": {"julgamento": "Unclear", "justificativa": "O artigo não fornece informações sobre se os pacientes e a equipe cirúrgica/anestésica estavam cegos à alocação, o que é frequentemente inviável ou não descrito em ensaios de intervenção técnica."},
  "cegamento_avaliadores_desfecho": {"julgamento": "Unclear", "justificativa": "Não há menção no texto sobre se os avaliadores dos desfechos de resultado estavam cegos à alocação dos grupos."},
  "dados_desfecho_incompletos": {"julgamento": "Low", "justificativa": "O artigo reporta explicitamente que 78 pacientes completaram o estudo, com 1 exclusão e 1 perda de seguimento, detalhando a análise dos dados disponíveis."},
  "relato_seletivo": {"julgamento": "Low", "justificativa": "O estudo está registrado no ClinicalTrials.gov (NCT04775576) e relata uma gama ampla de desfechos primários e secundários, incluindo hemodinâmicos, laboratoriais e de complicações."},
  "outros_vieses": {"julgamento": "Unclear", "justificativa": "Embora os autores admitam o pequeno tamanho da amostra e a falta de estudo de longo prazo como limitações, não há evidência clara no texto de outros vieses metodológicos graves além dos já identificados."},
  "risco_global": {"julgamento": "Unclear", "justificativa": "A combinação de uma ocultação de alocação de alto risco (envelopes) com a ausência de informação sobre cegamento leva a um julgamento global de risco de viés indeterminado."}
